    /// Returns `true` if this decision tree is guaranteed to match at runtime,
    /// that is, it can never reach a `Fail` node no matter the value being
    /// matched on. This is the case for exhaustive, irrefutable patterns such
    /// as the ones used in plain `let` bindings or `let assert`s whose pattern
    /// can't actually fail (e.g. destructuring a tuple or a single-variant
    /// custom type).
    ///
    pub fn always_matches(&self) -> bool {
        match self {
            Decision::Fail => false,
            Decision::Run { .. } => true,
            // A guard introduces a runtime condition that might not hold, so we
            // can't guarantee the tree always matches. Guards never appear in
            // `let`/`let assert` trees anyway.
            Decision::Guard { .. } => false,
            Decision::Switch {
                choices, fallback, ..
            } => {
                fallback.always_matches()
                    && choices.iter().all(|(_, decision)| decision.always_matches())
            }
        }
    }
